def separate_paren_groups(paren_string):
    open_braces = 0
    start_index = 0
    result = []
    for i, char in enumerate(paren_string):
        if char == '(':
            if open_braces == 0:
                start_index = i
            open_braces += 1
        elif char == ')':
            open_braces -= 1
            if open_braces == 0:
                result.append(paren_string[start_index:i+1])
    return result
