def generate_numbers(n, rules):
    queue = [n]
    visited = set()
    count = 0
    while queue:
        num = queue.pop(0)
        if num not in visited:
            visited.add(num)
            count += 1
            for rule in rules:
                new_num = apply_rule(num, rule)
                if new_num not in visited:
                    queue.append(new_num)
    return count

def apply_rule(num, rule):
    x, y = rule
    return int(str(num).replace(str(x), str(y)))
