def mod_inverse(a, b):
    gcd, x, _ = egcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

def egcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        gcd, x, y = egcd(b % a, a)
        return (gcd, y - (b // a) * x, x)
